/**
 * Corpus + golden-fixture access for the Python↔TS parity test.
 *
 * The corpus at `tools/agentprobe/suites/*.json` is **read-only**: this module never
 * writes it, and it never puts attack text into an error message — only `suite`/`id`
 * and sha256 digests — so a failing test cannot leak an attack into logs.
 *
 * The golden fixture is generated by `scripts/gen_golden.py`, which calls the Python
 * SafeHarness engine over the same corpus. Alignment is by `(suite, id)` **and** by the
 * sha256 of the attack text, so silent corpus drift (an edited attack, a re-wrapping,
 * an id reuse) is a loud error instead of a flaky assertion.
 *
 * Layout (relative to the plugin root `plugins/dsh-safeharness/`):
 *   tests/corpus.ts              <- this file
 *   tests/fixtures/golden.json   <- generated, committed
 *   ../../../tools/agentprobe/suites/*.json  (repo root)
 * @module
 */

import { createHash } from 'node:crypto'
import { readdirSync, readFileSync, statSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

/** One attack as it appears in the corpus, with the digest of its UTF-8 text. */
export interface CorpusAttack {
  /** Suite name, taken from the corpus file's `name` field (not the file name). */
  suite: string
  /** Attack id, unique inside its suite. */
  id: string
  /** The attack text. Never logged; only fed to the engine and hashed. */
  text: string
  /** Lowercase hex sha256 of `text` encoded as UTF-8. */
  textSha256: string
}

/** One golden entry: the Python engine's verdict for a corpus attack. */
export interface GoldenAttack {
  /** Attack id, unique inside its suite. */
  id: string
  /** sha256 of the attack text as the Python generator measured it. */
  text_sha256: string
  /** `len(text)` in Python (Unicode code points), stored for drift diagnostics. */
  text_chars: number
  /** `bool(InformPolicy._sanitize_value(text)[1])` — the pure-regex injection verdict. */
  inform_matched: boolean
  /** `bool(inspect_sql(text).dangerous)` — structural SQL danger, exfil included. */
  sql_dangerous: boolean
  /** `Verdict.reason_code` from SQL, else the inform code, else `null`. */
  reason_code: string | null
}

/** One suite in the golden fixture. */
export interface GoldenSuite {
  suite: string
  attacks: GoldenAttack[]
}

/** The whole generated fixture (`tests/fixtures/golden.json`). */
export interface GoldenFixture {
  /** ISO-8601 UTC; the only field that legitimately changes between runs. */
  generated_at_utc: string
  /** Python version that produced the fixture. */
  python: string
  /** Which Python entry point produced the verdicts, plus the compiled-pattern count. */
  engine_note: string
  suites: GoldenSuite[]
}

/** A corpus attack joined to its golden verdict. */
export interface GoldenJoin {
  attack: CorpusAttack
  golden: GoldenAttack
}

/** This file lives in `<plugin>/tests/`. */
const TESTS_DIR = dirname(fileURLToPath(import.meta.url))

/** Plugin root: `plugins/dsh-safeharness/`. */
export const pluginRoot = resolve(TESTS_DIR, '..')

/** Repository root of the SafeHarness Suite checkout, two levels above the plugin root. */
export const repoRoot = resolve(pluginRoot, '..', '..')

/** Path of the generated fixture. */
export const goldenPath = join(TESTS_DIR, 'fixtures', 'golden.json')

/** How to regenerate the fixture; quoted in every drift message. */
const REGENERATE_HINT =
  'regenerate it with `& $py -X utf8 scripts\\gen_golden.py` from the plugin root, ' +
  'with PYTHONPATH=<repo>\\src;<repo> (see scripts/gen_golden.py)'

/** Lowercase hex sha256 of `text` encoded as UTF-8 (matches Python's `hashlib.sha256`). */
export function sha256Hex(text: string): string {
  return createHash('sha256').update(text, 'utf8').digest('hex')
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function requireString(value: unknown, where: string): string {
  if (typeof value !== 'string') {
    throw new Error(`safeharness golden: ${where} must be a string`)
  }
  return value
}

function requireBoolean(value: unknown, where: string): boolean {
  if (typeof value !== 'boolean') {
    throw new Error(`safeharness golden: ${where} must be a boolean`)
  }
  return value
}

function requireNumber(value: unknown, where: string): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new Error(`safeharness golden: ${where} must be a finite number`)
  }
  return value
}

function requireArray(value: unknown, where: string): unknown[] {
  if (!Array.isArray(value)) {
    throw new Error(`safeharness golden: ${where} must be an array`)
  }
  return value
}

function errorText(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

/**
 * Locate `tools/agentprobe/suites`.
 *
 * Honours `SAFEHARNESS_CORPUS_DIR`, then the standard repo-relative path, then walks up
 * to four ancestors of the plugin root (covers running from a copied checkout). Throws
 * with every path it tried rather than silently returning an empty corpus.
 */
export function findCorpusDir(): string {
  const tried: string[] = []
  const override = process.env.SAFEHARNESS_CORPUS_DIR
  if (override !== undefined && override.trim() !== '') {
    const candidate = resolve(override)
    if (statSyncOrNull(candidate) === 'dir') return candidate
    tried.push(`${candidate} (SAFEHARNESS_CORPUS_DIR)`)
  }
  let base = pluginRoot
  for (let depth = 0; depth < 4; depth += 1) {
    const candidate = join(base, 'tools', 'agentprobe', 'suites')
    const kind = statSyncOrNull(candidate)
    if (kind === 'dir') return candidate
    tried.push(candidate)
    const parent = resolve(base, '..')
    if (parent === base) break
    base = parent
  }
  throw new Error(
    'safeharness golden: corpus directory `tools/agentprobe/suites` not found. ' +
      `Tried: ${tried.join(', ')}. Run the test from the plugin checkout ` +
      `(${pluginRoot}) or set SAFEHARNESS_CORPUS_DIR.`,
  )
}

function statSyncOrNull(path: string): 'file' | 'dir' | null {
  try {
    const stat = statSync(path)
    if (stat.isDirectory()) return 'dir'
    if (stat.isFile()) return 'file'
    return null
  } catch {
    return null
  }
}

/**
 * Read every `*.json` suite in the corpus and return the flattened attacks, in file order
 * (suite files sorted by file name, attacks in corpus order).
 *
 * @throws if the corpus is missing, unparsable or the shape is not
 *   `{name: string, attacks: [{id: string, text: string}, ...]}`.
 */
export function loadCorpus(): CorpusAttack[] {
  const dir = findCorpusDir()
  let names: string[]
  try {
    names = readdirSync(dir)
      .filter((name) => name.toLowerCase().endsWith('.json'))
      .sort()
  } catch (error) {
    throw new Error(`safeharness golden: cannot list corpus directory ${dir}: ${errorText(error)}`)
  }
  if (names.length === 0) {
    throw new Error(`safeharness golden: corpus directory ${dir} contains no *.json suites`)
  }

  const attacks: CorpusAttack[] = []
  const seen = new Set<string>()
  for (const name of names) {
    const path = join(dir, name)
    let raw: string
    try {
      // Explicit UTF-8: a locale-decoded read would corrupt CJK attacks (§9.10).
      raw = readFileSync(path, 'utf8')
    } catch (error) {
      throw new Error(`safeharness golden: cannot read corpus file ${name}: ${errorText(error)}`)
    }
    let parsed: unknown
    try {
      parsed = JSON.parse(raw)
    } catch (error) {
      throw new Error(`safeharness golden: corpus file ${name} is not valid JSON: ${errorText(error)}`)
    }
    if (!isRecord(parsed)) {
      throw new Error(`safeharness golden: corpus file ${name} must contain a JSON object`)
    }
    const suite = requireString(parsed['name'], `${name}: name`)
    const rawAttacks = requireArray(parsed['attacks'], `${name}: attacks`)
    for (const [index, value] of rawAttacks.entries()) {
      if (!isRecord(value)) {
        throw new Error(`safeharness golden: ${suite}[${index}] must be an object`)
      }
      const id = requireString(value['id'], `${suite}[${index}].id`)
      const text = requireString(value['text'], `${suite}/${id}.text`)
      const key = `${suite}\u0000${id}`
      if (seen.has(key)) {
        throw new Error(`safeharness golden: duplicate corpus attack id ${suite}/${id}`)
      }
      seen.add(key)
      attacks.push({ suite, id, text, textSha256: sha256Hex(text) })
    }
  }
  return attacks
}

/**
 * Read and structurally validate `tests/fixtures/golden.json`.
 *
 * @throws with a regeneration hint when the fixture is missing or malformed.
 */
export function loadGolden(): GoldenFixture {
  let raw: string
  try {
    raw = readFileSync(goldenPath, 'utf8')
  } catch (error) {
    throw new Error(
      `safeharness golden: cannot read ${goldenPath}: ${errorText(error)}. ` +
        `The fixture is generated, not hand-written — ${REGENERATE_HINT}.`,
    )
  }
  let parsed: unknown
  try {
    parsed = JSON.parse(raw)
  } catch (error) {
    throw new Error(`safeharness golden: ${goldenPath} is not valid JSON: ${errorText(error)}`)
  }
  if (!isRecord(parsed)) {
    throw new Error(`safeharness golden: ${goldenPath} must contain a JSON object`)
  }
  const fixtures = requireArray(parsed['suites'], 'golden.suites')
  const suites: GoldenSuite[] = []
  const seen = new Set<string>()
  for (const [suiteIndex, value] of fixtures.entries()) {
    if (!isRecord(value)) {
      throw new Error(`safeharness golden: suites[${suiteIndex}] must be an object`)
    }
    const suite = requireString(value['suite'], `suites[${suiteIndex}].suite`)
    const rawAttacks = requireArray(value['attacks'], `${suite}.attacks`)
    const goldenAttacks: GoldenAttack[] = []
    for (const [index, entry] of rawAttacks.entries()) {
      const where = `${suite}[${index}]`
      if (!isRecord(entry)) {
        throw new Error(`safeharness golden: ${where} must be an object`)
      }
      const id = requireString(entry['id'], `${where}.id`)
      const key = `${suite}\u0000${id}`
      if (seen.has(key)) {
        throw new Error(`safeharness golden: duplicate golden entry ${suite}/${id}`)
      }
      seen.add(key)
      const reasonCode = entry['reason_code']
      if (reasonCode !== null && typeof reasonCode !== 'string') {
        throw new Error(`safeharness golden: ${suite}/${id}.reason_code must be string or null`)
      }
      goldenAttacks.push({
        id,
        text_sha256: requireString(entry['text_sha256'], `${suite}/${id}.text_sha256`),
        text_chars: requireNumber(entry['text_chars'], `${suite}/${id}.text_chars`),
        inform_matched: requireBoolean(entry['inform_matched'], `${suite}/${id}.inform_matched`),
        sql_dangerous: requireBoolean(entry['sql_dangerous'], `${suite}/${id}.sql_dangerous`),
        reason_code: reasonCode,
      })
    }
    suites.push({ suite, attacks: goldenAttacks })
  }
  return {
    generated_at_utc: requireString(parsed['generated_at_utc'], 'golden.generated_at_utc'),
    python: requireString(parsed['python'], 'golden.python'),
    engine_note: requireString(parsed['engine_note'], 'golden.engine_note'),
    suites,
  }
}

/**
 * Align corpus attacks with golden verdicts by `(suite, id)` and verify the text digest.
 *
 * Every corpus attack must have a golden entry, every golden entry must exist in the
 * corpus, and `sha256(text)` must match `text_sha256` exactly. Any violation throws with
 * suite/id + digests only (never the attack text) and a regeneration hint.
 */
export function joinGolden(corpus: CorpusAttack[], golden: GoldenFixture): GoldenJoin[] {
  const goldenByKey = new Map<string, { suite: string; attack: GoldenAttack }>()
  for (const suite of golden.suites) {
    for (const attack of suite.attacks) {
      goldenByKey.set(`${suite.suite}\u0000${attack.id}`, { suite: suite.suite, attack })
    }
  }

  const joined: GoldenJoin[] = []
  const matchedKeys = new Set<string>()
  for (const attack of corpus) {
    const key = `${attack.suite}\u0000${attack.id}`
    const entry = goldenByKey.get(key)
    if (entry === undefined) {
      throw new Error(
        `safeharness golden: corpus attack ${attack.suite}/${attack.id} has no golden entry. ` +
          `The fixture is stale — ${REGENERATE_HINT}.`,
      )
    }
    if (entry.attack.text_sha256 !== attack.textSha256) {
      throw new Error(
        `safeharness golden: CORPUS DRIFTED for ${attack.suite}/${attack.id}: ` +
          `corpus text sha256=${attack.textSha256}, golden text sha256=${entry.attack.text_sha256}. ` +
          `The fixture must be regenerated from the current corpus — ${REGENERATE_HINT}.`,
      )
    }
    if (entry.attack.text_chars !== [...attack.text].length) {
      throw new Error(
        `safeharness golden: CORPUS DRIFTED for ${attack.suite}/${attack.id}: ` +
          `corpus text has ${[...attack.text].length} code points, golden records ` +
          `${entry.attack.text_chars} (sha256 matched — fixture metadata is stale).`,
      )
    }
    matchedKeys.add(key)
    joined.push({ attack, golden: entry.attack })
  }

  for (const key of goldenByKey.keys()) {
    if (matchedKeys.has(key)) continue
    const [suite = '?', id = '?'] = key.split('\u0000')
    throw new Error(
      `safeharness golden: golden entry ${suite}/${id} is not in the corpus. ` +
        `The fixture is stale — ${REGENERATE_HINT}.`,
    )
  }

  return joined
}

/** Convenience: load both sides and join them, in one call. */
export function loadJoin(): GoldenJoin[] {
  return joinGolden(loadCorpus(), loadGolden())
}
